def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return None

    change = new - old
    change_ratio = change / old
    percent_change = change_ratio * 100

    return {
        "value": percent_change,
        "trace": {
            "old_value": old,
            "new_value": new,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
